$s=db()->prepare('SELECT a.*,u.name FROM accounts a JOIN users u ON u.id=a.user_id WHERE u.name LIKE ? OR a.email LIKE ? OR a.student_id LIKE ? ORDER BY a.id DESC LIMIT 20 OFFSET '.(($page-1)*20));$s->execute([$like,$like,$like]);$users=$s->fetchAll();$title='Users — ZPPSU';$adminSection='users';$adminLayout=true;require __DIR__.'/includes/header.php';require __DIR__.'/includes/admin_layout.php';
