<div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th><th class="action-column">Actions</th></tr></thead><tbody><?php foreach($users as $user): ?><tr><td><button class="table-item-button" data-review="user" data-id="<?= (int)$user['id'] ?>"><span><strong class="truncate"><?= e($user['name']) ?></strong><small><?= e($user['student_id'] ?: 'No Student ID') ?></small></span></button></td><td><span class="truncate location-cell" title="<?= e($user['email']) ?>"><?= e($user['email']) ?></span></td><td><?= $user['role']==='admin' ? 'Administrator' : 'Student' ?></td><td><span class="admin-pill <?= $user['active'] ? 'approved' : 'archived' ?>"><?= $user['active'] ? 'Active' : 'Disabled' ?></span></td><td><details class="row-menu"><summary aria-label="Actions for <?= e($user['name']) ?>">&#8943;</summary><div><a href="admin_user.php?id=<?= (int)$user['id'] ?>" data-review="user" data-id="<?= (int)$user['id'] ?>">Edit account</a></div></details></td></tr><?php endforeach ?><?php if(!$users): ?><tr><td colspan="5" class="admin-empty"><strong>No matching accounts.</strong><small>Try a different name, email or Student ID.</small></td></tr><?php endif ?></tbody></table></div>
